import heapq

def stable_toposort(graph):
    if not graph:
        return []

    nodes = list(graph.keys())
    order_index = {node: i for i, node in enumerate(nodes)}
    indegree = {node: 0 for node in nodes}
    reverse_adj = {}

    # Validate dependencies and build reverse adjacency
    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep}")
            indegree[node] += 1
            reverse_adj.setdefault(dep, []).append(node)

    # Initialize heap with nodes that have no dependencies
    heap = []
    for node in nodes:
        if indegree[node] == 0:
            heapq.heappush(heap, (order_index[node], node))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for dependent in reverse_adj.get(node, []):
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, (order_index[dependent], dependent))

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result
