def schema_drift(expected, actual):
    """
    Compare two nested schema dicts and return a sorted list of dotted paths
    for missing fields, extra fields, or fields with different types.
    """
    results = []

    def get_all_leaf_paths(value, prefix):
        """Return all leaf paths under value (dict or string) as dotted strings."""
        if isinstance(value, dict):
            for k, v in value.items():
                new_prefix = f"{prefix}.{k}" if prefix else k
                results.extend(get_all_leaf_paths(v, new_prefix))
        else:
            # leaf
            results.append(prefix)
        return results

    def compare(node_exp, node_act, prefix):
        # Both are dicts at this point
        keys_exp = set(node_exp.keys())
        keys_act = set(node_act.keys())
        all_keys = keys_exp | keys_act

        for key in all_keys:
            path = f"{prefix}.{key}" if prefix else key

            if key not in keys_act:
                # missing field
                # report all leaf paths under expected[key]
                get_all_leaf_paths(node_exp[key], path)
            elif key not in keys_exp:
                # extra field
                get_all_leaf_paths(node_act[key], path)
            else:
                exp_val = node_exp[key]
                act_val = node_act[key]

                if isinstance(exp_val, dict) and isinstance(act_val, dict):
                    # both nested objects → recurse
                    compare(exp_val, act_val, path)
                else:
                    # check type difference
                    if isinstance(exp_val, str) and isinstance(act_val, str):
                        if exp_val != act_val:
                            results.append(path)
                    else:
                        # one is dict and the other isn't → type mismatch
                        results.append(path)

    compare(expected, actual, "")
    return sorted(results)
